'use strict';
let lang='en', selected=-1, draft=null, completed=false, returnFocus=null;
const copy={en:{help:'Help',emergency:'In immediate danger? Call 911.',emergencyText:'HighGround cannot dispatch emergency responders.',guidance:'911 guidance',demo:'DEMONSTRATION ONLY · No live alerts · No requests are sent',eyebrow:'HERE FOR TEXAS. HERE FOR YOU.',headline:'Care and support,<br><span>when you need it most.</span>',intro:'Find your next step for healthcare and essential support during and after a flood.',need:'What do you need help with?',services:['Medical Care','Medication','Safe Shelter','Transportation'],descriptions:['Find a path to care and medical support.','Explore help accessing essential prescriptions.','Find resources for temporary accommodation.','Explore options for getting to essential care.'],select:'Select a service, or tell us what you need.',chosen:'Selected:',cta:'Get Help Now',ctaNote:'Try a demo request · Nothing is sent to a provider',updates:'Flood updates',updatesNote:'Demo mode. Current conditions are not connected.',view:'View updates →',how:'How It Works',steps:['Tell us what you need','Review your details','See your next steps'],stepDesc:['Choose a service and share a general area.','Check your demo request before confirming.','Use official resources to seek real assistance.'],footer:'A little clarity. A little care. A way forward.',privacy:'Privacy',status:'Demo status',close:'Close dialog',formTitle:'What support do you need?',formNotice:'Demo only. Do not enter real personal or medical information. No one monitors this form.',service:'Service needed',choose:'Choose a service',other:'Not sure / other support',location:'City or ZIP code',locationNote:'Use a sample city or ZIP. Do not include a street address.',details:'Anything else? (optional)',detailsNote:'Use fictional details only. Do not include names, phone numbers, or medical records.',ack:'I understand this is a demo and will not send a request or arrange assistance.',review:'Review demo request',cancel:'Cancel',reviewTitle:'Review your demo request',edit:'Edit details',confirm:'Confirm demo only',reviewNote:'Confirming shows a local demonstration status. It does not contact a coordinator, reserve a place, or request transport.',done:'Demo complete. Request not sent.',doneNote:'No provider or emergency service has received this information. Do not wait here for assistance.',statusLabel:'Local demo only',next:'For real assistance',resource:'Contact 2-1-1 Texas for community resources. Availability and eligibility must be confirmed directly.',call211:'Call 211',visit211:'Visit 2-1-1 Texas',clear:'Clear demo details',noStatus:'No demo request has been completed in this page session.',updatesTitle:'Flood information',official:'Official sources · external links',officialNote:'These links open official websites. HighGround does not retrieve or verify their current data.',nws:'National Weather Service: forecasts & alerts',safety:'National Weather Service: flood safety',sample:'DEMO SCENARIO · NOT A REAL ALERT',sampleText:'Example: flooding may disrupt access to care. Check official alerts and local instructions before making travel decisions.',source:'Source: fictional training scenario. No observation time; no live feed.',emergencyTitle:'Need emergency help?',emergencyBody:'If you are in immediate danger or have a life-threatening medical emergency, call 911. This website cannot contact responders or locate you.',floodSafety:'Do not walk or drive through floodwater. Follow instructions from local emergency officials.',call911:'Call 911',emergencyNote:'This button opens your device’s phone app. It does not place a call automatically. If this device cannot make calls, use a phone to dial 911.',helpTitle:'A clear next step',helpBody:'Choose a service and try the short demo form. You can review and edit before confirming. There is no account, dispatch service, or provider matching.',helpExtra:'For actual community services, contact 2-1-1 Texas. For immediate danger, call 911.',privacyTitle:'Your privacy in this demo',privacyBody:'Form details are held only in this page’s memory. They are not sent, saved to browser storage, or shared. Reloading the page or clearing the demo removes them. Use fictional information only. Chat messages are separate: when AI is connected, your messages and recent conversation are sent to OpenAI for replies. Avoid sensitive information. External resource websites have their own privacy policies.',offline:'You appear to be offline. External resources require a connection. In an emergency, use a phone to call 911.',notProvided:'Not provided'},es:{help:'Ayuda',emergency:'¿Peligro inmediato? Llama al 911.',emergencyText:'HighGround no puede enviar servicios de emergencia.',guidance:'Orientación del 911',demo:'SOLO DEMOSTRACIÓN · Sin alertas en vivo · No se envían solicitudes',eyebrow:'POR TEXAS. CONTIGO.',headline:'Atención y apoyo,<br><span>cuando más lo necesitas.</span>',intro:'Encuentra el siguiente paso para recibir atención y apoyo esencial durante y después de una inundación.',need:'¿Con qué necesitas ayuda?',services:['Atención médica','Medicamentos','Refugio seguro','Transporte'],descriptions:['Explora recursos de atención y apoyo médico.','Busca ayuda para acceder a recetas esenciales.','Encuentra recursos de alojamiento temporal.','Explora opciones para llegar a la atención esencial.'],select:'Elige un servicio o cuéntanos qué necesitas.',chosen:'Seleccionado:',cta:'Obtener ayuda ahora',ctaNote:'Prueba una solicitud de demostración · No se envía a proveedores',updates:'Información de inundaciones',updatesNote:'Modo demo. Sin conexión a las condiciones actuales.',view:'Ver información →',how:'Cómo funciona',steps:['Cuéntanos qué necesitas','Revisa los detalles','Consulta los siguientes pasos'],stepDesc:['Elige un servicio y una zona general.','Revisa tu solicitud de demo antes de confirmar.','Usa recursos oficiales para buscar ayuda real.'],footer:'Claridad, atención y un camino para seguir.',privacy:'Privacidad',status:'Estado de demo',close:'Cerrar ventana',formTitle:'¿Qué apoyo necesitas?',formNotice:'Solo demo. No ingreses información personal o médica real. Nadie supervisa este formulario.',service:'Servicio necesario',choose:'Elige un servicio',other:'No sé / otro apoyo',location:'Ciudad o código postal',locationNote:'Usa una ciudad o código de ejemplo. No incluyas una dirección.',details:'¿Algo más? (opcional)',detailsNote:'Usa solo información ficticia. No incluyas nombres, teléfonos ni expedientes médicos.',ack:'Entiendo que es una demo y que no enviará una solicitud ni coordinará ayuda.',review:'Revisar solicitud de demo',cancel:'Cancelar',reviewTitle:'Revisa tu solicitud de demo',edit:'Editar detalles',confirm:'Confirmar solo la demo',reviewNote:'Confirmar muestra un estado de demostración local. No contacta a coordinadores, reserva alojamiento ni solicita transporte.',done:'Demo completada. Solicitud no enviada.',doneNote:'Ningún proveedor ni servicio de emergencia ha recibido esta información. No esperes aquí para recibir ayuda.',statusLabel:'Solo demo local',next:'Para obtener ayuda real',resource:'Contacta a 2-1-1 Texas para consultar recursos comunitarios. Confirma disponibilidad y requisitos directamente.',call211:'Llamar al 211',visit211:'Visitar 2-1-1 Texas',clear:'Borrar los datos de demo',noStatus:'No se ha completado una solicitud de demo en esta sesión.',updatesTitle:'Información de inundaciones',official:'Fuentes oficiales · enlaces externos',officialNote:'Estos enlaces abren sitios oficiales. HighGround no obtiene ni verifica sus datos actuales.',nws:'Servicio Meteorológico Nacional: pronósticos y alertas',safety:'Servicio Meteorológico Nacional: seguridad ante inundaciones',sample:'ESCENARIO DE DEMO · NO ES UNA ALERTA REAL',sampleText:'Ejemplo: las inundaciones pueden interrumpir el acceso a la atención. Consulta alertas oficiales e instrucciones locales antes de viajar.',source:'Fuente: escenario ficticio de práctica. Sin hora de observación ni datos en vivo.',emergencyTitle:'¿Necesitas ayuda de emergencia?',emergencyBody:'Si estás en peligro inmediato o tienes una emergencia médica que amenaza la vida, llama al 911. Este sitio no puede contactar a los servicios de emergencia ni localizarte.',floodSafety:'No camines ni conduzcas por agua de inundación. Sigue las instrucciones de las autoridades locales.',call911:'Llamar al 911',emergencyNote:'Este botón abre la aplicación de teléfono. No realiza una llamada automáticamente. Si este dispositivo no puede llamar, usa un teléfono para marcar 911.',helpTitle:'Un siguiente paso claro',helpBody:'Elige un servicio y prueba el formulario de demo. Puedes revisar y editar antes de confirmar. No hay cuentas, envío de ayuda ni asignación de proveedores.',helpExtra:'Para servicios comunitarios reales, contacta a 2-1-1 Texas. En peligro inmediato, llama al 911.',privacyTitle:'Tu privacidad en esta demo',privacyBody:'Los datos solo se mantienen en la memoria de esta página. No se envían, guardan en el almacenamiento del navegador ni comparten. Recargar la página o borrar la demo los elimina. Usa solo información ficticia. El chat es independiente: cuando la IA está conectada, tus mensajes y el contexto reciente se envían a OpenAI para responder. Evita información sensible. Los sitios externos tienen sus propias políticas de privacidad.',offline:'Parece que no tienes conexión. Los recursos externos requieren internet. En una emergencia, usa un teléfono para llamar al 911.',notProvided:'Sin información'}};
const paths={drop:'M14 3C10 9 5 13 5 18a9 9 0 0 0 18 0c0-5-5-9-9-15Z M10 19h8 M14 15v8',medical:'M10 4h8v7h7v8h-7v7h-8v-7H3v-8h7Z',pill:'M8 24a7 7 0 0 1-5-12L14 1a7 7 0 0 1 10 10L13 22a7 7 0 0 1-5 2Z M9 7l10 10',home:'M3 14 15 4l12 10 M6 12v15h18V12 M12 27v-9h6v9',car:'M5 13l3-8h14l3 8 M3 14h24v10H3Z M7 24v3 M23 24v3 M7 18h2 M21 18h2',alert:'M15 3 28 26H2Z M15 11v7 M15 22v.1',water:'M2 12c4-5 7 5 12 0s8 5 14 0 M2 20c4-5 7 5 12 0s8 5 14 0 M15 2v5',arrow:'M5 15h20 M19 9l6 6-6 6'};
const icon=n=>`<svg aria-hidden="true" viewBox="0 0 30 30"><path d="${paths[n]}"/></svg>`;
const t=()=>copy[lang]; const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dialog=document.querySelector('#dialog');
function render(){renderExperience();}
function show(title,body){document.querySelector('#dialog-body').innerHTML=`<h2 id="dialog-title" tabindex="-1">${title}</h2>${body}`;if(!dialog.open){returnFocus=document.activeElement;dialog.showModal()}document.querySelector('#dialog-title').focus();dialog.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>dialog.close());}
function resources(){const c=t();return `<h3>${c.next}</h3><p>${c.resource}</p><div class="actions"><a class="button" href="tel:211">${c.call211}</a><a href="https://www.211texas.org/" class="soft button">${c.visit211}</a></div>`}
function open(type){const c=t();if(type==='request'){draft={service:selected<0?'':String(selected),location:'',details:''};form();return}if(type==='emergency'){show(c.emergencyTitle,`<p class="notice danger">${c.emergencyBody}</p><p>${c.floodSafety}</p><a class="button danger-link" href="tel:911">${c.call911}</a><p>${c.emergencyNote}</p><a href="https://www.weather.gov/safety/flood-during">${c.safety}</a>`)}if(type==='help')show(c.helpTitle,`<p>${c.helpBody}</p><p class="notice">${c.helpExtra}</p>${resources()}`);if(type==='privacy')show(c.privacyTitle,`<p>${c.privacyBody}</p>`);if(type==='updates')show(c.updatesTitle,`<p class="notice">${c.updatesNote}</p><h3>${c.official}</h3><p>${c.officialNote}</p><ul><li><a href="https://www.weather.gov/">${c.nws}</a></li><li><a href="https://www.weather.gov/safety/flood">${c.safety}</a></li></ul><hr><p><span class="badge">${c.sample}</span></p><p>${c.sampleText}</p><p class="field-note">${c.source}</p>`);if(type==='status')status();}
function form(){const c=t();show(c.formTitle,`<p class="notice">${c.formNotice}</p><form id="request-form"><label>${c.service}<select id="service" name="service" required><option value="">${c.choose}</option>${[...c.services,c.other].map((s,i)=>`<option value="${i}" ${draft.service===String(i)?'selected':''}>${s}</option>`).join('')}</select></label><label>${c.location}<input id="location" name="location" required maxlength="80" value="${escape(draft.location)}" aria-describedby="location-note" autocomplete="off"><span class="field-note" id="location-note">${c.locationNote}</span></label><label>${c.details}<textarea name="details" id="details" maxlength="500" rows="3" aria-describedby="details-note">${escape(draft.details)}</textarea><span class="field-note" id="details-note">${c.detailsNote}</span></label><label class="check"><input type="checkbox" required name="ack">${c.ack}</label><div class="actions"><button type="submit" class="primary">${c.review}</button><button type="button" class="soft" data-close>${c.cancel}</button></div></form>`);document.querySelector('#request-form').onsubmit=e=>{e.preventDefault();const location=document.querySelector('#location');if(!location.value.trim()){location.setCustomValidity(lang==='en'?'Enter a sample city or ZIP code.':'Ingresa una ciudad o código de ejemplo.');location.reportValidity();return}draft={service:document.querySelector('#service').value,location:location.value.trim(),details:document.querySelector('#details').value.trim()};review()};document.querySelector('#location').oninput=e=>e.target.setCustomValidity('');}
function summary(){const c=t();return `<dl class="summary"><dt>${c.service}</dt><dd>${escape([...c.services,c.other][Number(draft.service)])}</dd><dt>${c.location}</dt><dd>${escape(draft.location)}</dd><dt>${c.details}</dt><dd>${escape(draft.details||c.notProvided)}</dd></dl>`}
function review(){const c=t();show(c.reviewTitle,`<p class="notice">${c.reviewNote}</p>${summary()}<div class="actions"><button class="primary" id="confirm">${c.confirm}</button><button class="soft" id="edit">${c.edit}</button><button class="text-button" data-close>${c.cancel}</button></div>`);document.querySelector('#edit').onclick=form;document.querySelector('#confirm').onclick=()=>{completed=true;draft=null;status()};}
function status(){const c=t();show(completed?c.done:c.status,completed?`<span class="badge">${c.statusLabel}</span><div class="status"><p><strong>${c.doneNote}</strong></p><p>${c.emergency}</p><a href="tel:911">${c.call911}</a></div>${resources()}<div class="actions"><button class="soft" id="clear">${c.clear}</button></div>`:`<p>${c.noStatus}</p>${resources()}`);if(completed)document.querySelector('#clear').onclick=()=>{completed=false;draft=null;selected=-1;dialog.close();render();document.querySelector('[data-action="status"]').focus()};}
document.querySelector('.close').onclick=()=>dialog.close();dialog.addEventListener('close',()=>{draft=null;if(returnFocus?.isConnected)returnFocus.focus()});for(const event of ['online','offline'])window.addEventListener(event,()=>{document.querySelector('#offline').hidden=navigator.onLine});render();
